// 1. Veriyi Al (Yapay Zeka Çıktısı)
const root = $input.item.json;
let rawText = "";

// AI yanıtını bulmaya çalış
if (root.content && root.content.parts && root.content.parts[0]) {
   rawText = root.content.parts[0].text;
} else if (root.text) {
   rawText = root.text;
} else if (root.response && root.response.text) {
   rawText = root.response.text;
} else {
   // AI yanıtı yoksa bile akış bozulmasın, boş dönelim.
   rawText = "{}"; 
}

// --- YENİ EKLENEN KISIMLAR BAŞLANGIÇ ---

// A. Mail Kategorisini Al (Webhook'tan gelen veri)
// Eğer veri gelmezse varsayılan olarak "general" ata.
const mailCategory = root.category || "general";

// B. Giden Mail Kontrolü (is_outgoing)
// root.owner_email: Senin mail adresin (Python'dan gönderdiğimiz)
// root.from: Maili gönderen kişi
const ownerEmail = root.owner_email || "hkanoer@gmail.com"; // Eğer owner_email yoksa bunu baz al
const sender = root.from || "";

// --- YENİ EKLENEN KISIMLAR BİTİŞ ---


// 2. Temizle ve Parse Et
const cleanText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

try {
  let parsedData = {};
  // Eğer AI boş döndüyse hata vermesin diye kontrol
  if (cleanText && cleanText !== "{}") {
      parsedData = JSON.parse(cleanText);
  }

  let tasks = [];
  let voiceScript = parsedData.voice_script || "";

  // Görevleri listeye çevir
  if (parsedData.tasks && Array.isArray(parsedData.tasks)) {
      tasks = parsedData.tasks;
  } else if (Array.isArray(parsedData)) {
      tasks = parsedData;
  }

  // 🔥 SENARYO 1: GÖREV YOKSA (Sadece Bilgilendirme)
  if (tasks.length === 0) {
      return [
          {
              json: {
                  has_tasks: false,
                  voice_script: voiceScript,
                  summary: "Bilgilendirme", // UI bozulmasın diye
              }
          }
      ];
  }

  // 🔥 SENARYO 2: GÖREV VARSA (Parçala ve Dağıt)
  return tasks.map(task => {
      return {
          json: {
              ...task, // AI'dan gelen task detayları (summary, date vs.)
              has_tasks: true,
              voice_script: voiceScript,
          }
      };
  });

} catch (error) {
  // JSON patlarsa akışı durdurma, hata objesi dön
  return [{ 
      json: { 
          voice_script: "Veri işlenirken hata oluştu: " + error.message, 
          has_tasks: false,
      } 
  }];
}

// ====================================================================
// AYARLAR
// ====================================================================
let mergeDugumAdi = 'Merge';
const kaynakDugumAdi = 'JSON Temizleyici'; // <-- KATEGORİ VE SES KAYNAĞI

// Merge ismini otomatik düzelt
try { if ($('merg') && $('merg').first()) mergeDugumAdi = 'merg'; } catch(e) {}

// ====================================================================
// 1. ÖNCE KAYNAK VERİLERİ (JSON TEMİZLEYİCİ) ÇEK
// ====================================================================
let kaynakVeriler = [];
try {
    kaynakVeriler = $(kaynakDugumAdi).all().map(item => item.json);
} catch(e) {
    kaynakVeriler = [];
}

// ====================================================================
// 🔥 KRİTİK KONTROL: EĞER GÖREV YOKSA HEMEN BİTİR
// ====================================================================
// Kaynak veriye bakıyoruz. Eğer "has_tasks: false" ise veya veri boşsa
// Merge düğümünü beklemeden direkt sesli metni dönüyoruz.
if (kaynakVeriler.length > 0) {
    const kaynak = kaynakVeriler[0];

    // Görev yok bayrağı var mı?
    if (kaynak.has_tasks === false) {
        return [
            {
                json: {
                    cevap: [], // Görev listesi boş
                    sesli_okuma: kaynak.voice_script || kaynak.sesli_okuma || "Bilgilendirme mesajı alındı.",
                    tip: "bilgilendirme" // Tip değişti
                }
            }
        ];
    }
}

// ====================================================================
// 2. MERGE SONUÇLARINI ÇEK (Google/Outlook Çıktıları)
// (Sadece görev varsa burası çalışır)
// ====================================================================
const mergeResults = [];
let runIndex = 0;
let loopDevam = true;

while (loopDevam) {
    try {
        const veriler = $(mergeDugumAdi).all(0, runIndex);
        if (veriler.length === 0) loopDevam = false;
        else { mergeResults.push(...veriler); runIndex++; }
    } catch (error) { loopDevam = false; }
}

// ====================================================================
// 3. RAPORU OLUŞTUR
// ====================================================================
const gorevHaritasi = {};
const siraliBasliklar = []; 

mergeResults.forEach(item => {
    const veri = item.json;

    // Başlık bul
    let baslik = veri.baslik || veri.summary || veri.subject;
    if (!baslik && veri.gorev_verisi) baslik = veri.gorev_verisi.summary;
    if (!baslik && veri.talep_edilen_gorev) baslik = veri.talep_edilen_gorev.baslik;
    if (!baslik && veri.id) baslik = "İsimsiz Etkinlik";

    if (!baslik) return;

    if (!gorevHaritasi[baslik]) {
        gorevHaritasi[baslik] = {
            baslik: baslik,
            platformlar: [],
            durum: "success",
            hata: null,
            kategori: "task", // Geçici
            baslangic: null,
            bitis: null,
            detay: null
        };
        siraliBasliklar.push(baslik);
    }

    const kayit = gorevHaritasi[baslik];

    // Detayları doldur
    let startT = veri.start?.dateTime || veri.start?.date || veri.saat;
    if (!startT && veri.gorev_verisi) startT = veri.gorev_verisi.start_time;
    if (startT) kayit.baslangic = startT;

    let endT = veri.end?.dateTime || veri.end?.date || veri.bitis;
    if (!endT && veri.gorev_verisi) endT = veri.gorev_verisi.end_time;
    if (endT) kayit.bitis = endT;

    let desc = veri.description || veri.bodyPreview || veri.detay;
    if (!desc && veri.gorev_verisi) desc = veri.gorev_verisi.description;
    if (desc && (!kayit.detay || desc.length > kayit.detay.length)) kayit.detay = desc;

    // Platform ve Durum
    if (veri.htmlLink) kayit.platformlar.push("Google");
    else if (veri["@odata.context"] || (veri.id && !veri.htmlLink)) kayit.platformlar.push("Outlook");
    else if (veri.durum === 'dolu' || String(veri["müsait "]) === "false" || veri.karar_temiz === false) {
        kayit.durum = "error";
        kayit.hata = veri.sebep || "Saat uygun değil";
    }
});

// Listeyi Hazırla
const finalGorevListesi = [];

siraliBasliklar.forEach(baslik => {
    const gorev = gorevHaritasi[baslik];

    let kullaniciMesaji = "";
    if (gorev.durum === "error") {
        let sebep = Array.isArray(gorev.hata) ? gorev.hata.join(", ") : gorev.hata;
        kullaniciMesaji = `⚠️ EKLENEMEDİ: ${sebep}`;
    } else {
        const platformlar = [...new Set(gorev.platformlar)].join(" ve ");
        kullaniciMesaji = `${platformlar} takvimine başarıyla eklendi.`;
    }

    finalGorevListesi.push({
        "baslik": gorev.baslik,
        "kategori": "task", 
        "baslangic": gorev.baslangic,
        "bitis": gorev.bitis,
        "detay": gorev.detay || "",
        "durum": gorev.durum,
        "kullanici_mesaji": kullaniciMesaji
    });
});

// ====================================================================
// 4. ADIM: KATEGORİ ENJEKSİYONU (Sıralı Eşleştirme)
// ====================================================================
finalGorevListesi.forEach((gorev, index) => {
    if (kaynakVeriler[index]) {
        const dogruKategori = kaynakVeriler[index].category || kaynakVeriler[index].kategori;
        if (dogruKategori) gorev.kategori = dogruKategori;
    }
});

// ====================================================================
// 5. ADIM: SESLİ METNİ BUL VE ÇIKTIYA EKLE
// ====================================================================
let sesliMetin = "İşlem tamamlandı."; // Varsayılan

// Kaynak verilerin İLK elemanından sesi al
if (kaynakVeriler.length > 0) {
    const kaynak = kaynakVeriler[0];
    if (kaynak.voice_script) sesliMetin = kaynak.voice_script;
    else if (kaynak.sesli_okuma) sesliMetin = kaynak.sesli_okuma;
}

// ====================================================================
// 6. ÇIKTI
// ====================================================================
return [
    {
        json: {
            cevap: finalGorevListesi,
            sesli_okuma: sesliMetin,
            tip: "gorev_listesi"
        }
    }
];

// 1. Merge node'undan gelen sonuçları al (Google ve Outlook tarama sonuçları)
const results = $input.all();

let googleDolu = false;
let outlookDolu = false;
let bulunanEtkinlikler = [];

// 2. Çakışma Kontrolü
results.forEach(item => {
  const veri = item.json;
  if (veri.id) {
    if (veri.htmlLink) {
      googleDolu = true;
      bulunanEtkinlikler.push(`Google: ${veri.summary}`);
    } else if (veri.webLink || veri['@odata.etag']) {
      outlookDolu = true;
      bulunanEtkinlikler.push(`Outlook: ${veri.subject}`);
    }
  }
});

// 3. REFERANS VERİSİNİ AL (Gemini / JSON Temizleyici)
let geminiDetay = {};
try {
  const anaVeri = $('JSON Temizleyici').first().json;
  if (anaVeri.ham_veri && anaVeri.ham_veri[0]) {
      geminiDetay = anaVeri.ham_veri[0];
  }
} catch (e) {
  // Hata olursa boş obje kalsın
}

// --- 4. YENİ EKLENEN KISIM: GOREV DONGU VERİSİNİ AL ---
let gorevDonguVerisi = {};
try {
  // 'Gorev Dongu' düğümünden o anki veriyi çeker.
  // .first() komutu "eşleştirme hatası" almadan veriyi getirir.
  gorevDonguVerisi = $('Gorev Dongu').item.json;
} catch (e) {
  gorevDonguVerisi = { hata: "Gorev Dongu verisi çekilemedi" };
}
// -------------------------------------------------------

// 5. Karar Ver
const yolTemiz = !googleDolu && !outlookDolu;

// 6. ÇIKTIYI HAZIRLA
return [
  {
    json: {
      karar_temiz: yolTemiz,

      // Kullanıcıya gidecek mesaj
      mesaj: yolTemiz ? "Müsait" : `⚠️ Çakışma Var: ${bulunanEtkinlikler.join(", ")}`,

      // Çakışan etkinliklerin listesi
      cakisma_detay: bulunanEtkinlikler,

      // Görev detayları (Gemini'den gelen)
      talep_edilen_gorev: {
          baslik: geminiDetay.summary || "Bilinmiyor",
          kullanici_mesaji: geminiDetay.display_text || "",
          saat: geminiDetay.start_time || "",
          detay: geminiDetay.description || ""
      },

      // --- BURAYI EKLEDİM: GOREV DONGU ÇIKTISI ---
      // Artık bir sonraki adımda $json.gorev_verisi... diyerek
      // Loop içindeki tüm verilere ulaşabilirsiniz.
      gorev_verisi: gorevDonguVerisi
      // -------------------------------------------
    }
  }
];
